<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Employee extends Model{protected $guarded=[];protected function casts():array{return['hire_date'=>'date','date_of_birth'=>'date','basic_salary'=>'decimal:2'];}public function property(){return $this->belongsTo(Property::class);}public function user(){return $this->belongsTo(User::class);}public function department(){return $this->belongsTo(Department::class);}public function position(){return $this->belongsTo(JobPosition::class,'job_position_id');}public function contracts(){return $this->hasMany(EmploymentContract::class);}public function attendance(){return $this->hasMany(AttendanceRecord::class);}public function leaveRequests(){return $this->hasMany(LeaveRequest::class);}public function payrollComponents(){return $this->belongsToMany(PayrollComponent::class,'employee_payroll_components')->withPivot(['value','effective_from','effective_to'])->withTimestamps();}public function getFullNameAttribute():string{return trim($this->first_name.' '.$this->other_names.' '.$this->last_name);}}